/* =============================================================================
   build-db-bundle.mjs — concatenate every migration into ONE .sql file.

   Why: when the Worker is deployed from GitHub, the database tables have to be
   created by hand in the Cloudflare dashboard (D1 -> your database -> Console).
   Pasting three files in the right order is fiddly and easy to get wrong, so
   this produces a single file that can be pasted once.

   It is GENERATED — never edit the output. Edit the numbered migrations in
   multiplayer/db/migrations/ and run `npm run db:bundle` again.

   Usage: node build-db-bundle.mjs
   ============================================================================= */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const DIR = path.join(ROOT, 'multiplayer', 'db', 'migrations');
const OUT = path.join(ROOT, 'multiplayer', 'db', 'apply-all.sql');

const files = fs.readdirSync(DIR)
  .filter(f => f.endsWith('.sql'))
  .sort();                                   /* 0001_, 0002_, 0003_ … in order */

if (!files.length) {
  console.error('No migrations found in ' + DIR);
  process.exit(1);
}

const parts = [
  '-- =============================================================================',
  '-- Viber Brawl — COMPLETE DATABASE SETUP, in one file.',
  '--',
  '-- GENERATED by `npm run db:bundle`. Do not edit this file directly.',
  '--',
  '-- How to use it:',
  '--   1. Cloudflare dashboard -> Storage & Databases -> D1 -> your database',
  '--   2. Open the "Console" tab',
  '--   3. Paste this whole file and run it',
  '--',
  '-- It is safe to run more than once: every statement uses IF NOT EXISTS or',
  '-- INSERT OR IGNORE, so it will not duplicate anything or destroy data.',
  '--',
  '-- Migrations included: ' + files.join(', '),
  '-- =============================================================================',
  ''
];

for (const f of files) {
  const sql = fs.readFileSync(path.join(DIR, f), 'utf8').trimEnd();
  parts.push('-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>');
  parts.push('-- ' + f);
  parts.push('-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>');
  parts.push(sql);
  parts.push('');
}

const bundle = parts.join('\n');
fs.writeFileSync(OUT, bundle);

const kb = (s) => (Buffer.byteLength(s, 'utf8') / 1024).toFixed(1) + ' KB';
console.log('Viber Brawl — database bundle');
console.log('─'.repeat(64));
for (const f of files) {
  console.log('  + ' + f.padEnd(42) + kb(fs.readFileSync(path.join(DIR, f), 'utf8')));
}
console.log('  = ' + path.relative(ROOT, OUT).replace(/\\/g, '/').padEnd(42) + kb(bundle));
console.log('─'.repeat(64));
console.log('Paste multiplayer/db/apply-all.sql into the D1 console.');
